#!/usr/bin/env python3
"""يولّد ch{2..5}/00_README_MAZIN.md من ملفات الصور الفردية الحالية. الاستعمال: python3 make_readme.py"""
import re,glob,os
names={2:'الفصل الثاني — الجزيرة (سيف وآدم)',3:'الفصل الثالث — السوق (حليمة ويونس)',4:'الفصل الرابع — الأطلال (هالة والحاج عثمان)',5:'الفصل الخامس — الضفة الهادئة (رحاب)'}
tips={
2:"- **c2-l1** (الممر الضحل): 5 أحجار على قطر من الضفة نحو الجزيرة، والتيار **من اليسار إلى اليمين**. الآمن خلفه ماء هادئ، وغير الآمن خلفه رغوة أو دوّامة. ارفض الصورة إن لم يظهر الفرق بوضوح.\n- **c2-l2**: القصبات الأربع المائلة مع الماء (25 إلى 35 درجة) وبقية القصب قائم. هذا ما تعتمد عليه الدلائل، فتأكد منه.\n- **star-sign-1..5**: خمس أيقونات متقاربة الشكل، الفرق في العلامة.\n- **knot-red/blue/yellow/green**: أربع عقد **بنفس الشكل والسماكة**، يتغير اللون فقط.",
3:"- **c3-l1 وc3-l4 وc3-l7**: خلفيات السوق. لا لافتات نصية.\n- **spice-***: أربع توابل يجب أن يميّزها الشكل واللون فوراً.\n- **bead-blue / copper-weight**: عنصران بسيطان، لا تعقّدهما.",
4:"- **c4-l4 (ممر المشاعل)**: أصعب صورة في المشروع: 8 محطات **منصّات حجرية** في قاعة بزاوية عالية، بعضها عليه مشعل مشتعل وبعضها مطفأ. إن لم تنجح بعد 3 محاولات فاتركها وأخبرني.\n- **c4-l2-puzzle**: لوحة حجرية **مربّعة تماماً** بإطار مستقيم، **عين في المركز**، **مجرى ماء من الأعلى للأسفل**، إضاءة منتظمة بلا ظلال تقطع الحواف (ستُقصّ إلى 9 حجارة). ارفض أي صورة مائلة.\n- **c4-l1**: ست علامات على الجدار: أربع في صف التسلسل ونجمة وقصبة زخرفة أسفله.\n- **carve-***: نقوش حجرية صغيرة.",
5:"- **c5-l2 وc5-l3**: صورتان تعتمد عليهما الدلائل (علامة عند الحافة اليسرى لكل قطعة في l2، و7 عقد منها قطعتان مموّهتان في l3). ارفض إن لم تظهر.\n- **notebook-safiya / brass-scale / stone-key**: ثلاث أيقونات لأزواج لعبة الذاكرة، يجب أن تتمايز.\n- **symbol-c5**: رمز الخيط بنفس أسلوب symbol-c1..c4."}
TYPE={'bg':'خلفية','char':'شخصية','icon':'أيقونة'}; SIZE={'bg':'1536×1024','char':'1024×1024','icon':'1024×1024'}
for n in (2,3,4,5):
    rows=[]
    for f in sorted(glob.glob(f"ch{n}/[0-9][0-9]_*.md")):
        if "/00_" in f: continue
        s=open(f,encoding='utf-8').read()
        d=re.search(r"الملف: `public/art/([^`]+)`",s).group(1)
        kind='icon' if d.startswith('items/') else ('char' if d.startswith('chars/') else 'bg')
        num,iid=re.match(r"(\d+)_(.+)\.md",os.path.basename(f)).groups()
        t=re.search(r"الطبقة (\w)",s); t=t.group(1) if t else 'B'
        if iid.endswith('-puzzle'): t='A'; size='1024×1024 (مربّعة)'
        else: size=SIZE[kind]
        ref=re.search(r"المرجع المرفق: ([^\n]+)",s).group(1)
        extra=""
        if kind=='char':
            m=re.search(r"_references/([\w-]+neutral\.png)",s)
            if m: extra=f" + `_references/{m.group(1)}`"
        rows.append((int(num),iid,kind,size,t,extra))
    A=[r for r in rows if r[4]=='A']; B=[r for r in rows if r[4]!='A']
    g={'bg':[],'char':[],'icon':[]}
    for r in sorted(rows,key=lambda r:(r[4]!='A',r[0])): g[r[2]].append(r)
    fmt=lambda rs:"، ".join(f"{r[0]:02d} {r[1]}{'' if r[4]=='A' else ' (B)'}" for r in rs)
    def ref(r):
        if r[2]=='icon': return "**لا شيء** (الملف فقط)"
        if r[2]=='bg': return "`00_RULES` + `village.jpg`"
        return "`00_RULES` + `nour.png`"+r[5]
    def table(rs): return ["| # | اسم الحفظ | النوع | المقاس | ما ترفقه |","|---|---|---|---|---|"]+[f"| {r[0]:02d} | `{r[1]}.png` | {TYPE[r[2]]} | {r[3]} | {ref(r)} |" for r in rs]
    L=[f"# دليل مازن — توليد صور {names[n]}","",f"**عدد الصور: {len(rows)}** (الطبقة A لازمة للتسليم: {len(A)}، الطبقة B تحسينية: {len(B)}). اقرأه مرة واحدة.","",
    "## ما في هذا المجلد","- `00_RULES_FOR_GEMINI.md`: قواعد عامة لجيمناي (للخلفيات والشخصيات فقط).","- `_references/`: `village.jpg` للخلفيات و`nour.png` للشخصيات، وصور وجه neutral للتعابير الجديدة إن وُجدت.",f"- ملفات `01_...md` إلى `{len(rows):02d}_...md`: ملف لكل صورة فيه اسم الحفظ والمقاس والبرومبت وفحص القبول.","",
    "## خطة المحادثات الثلاث",
    f"**محادثة 1: الخلفيات ({len(g['bg'])})**: ارفع `00_RULES_FOR_GEMINI.md` + `_references/village.jpg` مرة واحدة، ثم ملفاً ملفاً: {fmt(g['bg'])}",
    f"**محادثة 2: الشخصيات ({len(g['char'])})**: ارفع القواعد + `_references/nour.png` مرة واحدة، ثم: {fmt(g['char'])}. (للتعابير الجديدة ارفع معها صورة neutral الخاصة بالشخصية.)",
    f"**محادثة 3: الأيقونات ({len(g['icon'])})**: **بلا مرجع وبلا قواعد**. ابدأ بالأولى ثم التالية: {fmt(g['icon'])}",
    "(B) تحسينية: للآخر. ملف واحد في كل رسالة، واكتب «نفّذ هذا الملف: ولّد صورة واحدة فقط، واكتب تحتها اسم الملف». إن انحرف الأسلوب أو ظهر مشهد خلف أيقونة فافتح محادثة جديدة لباقي صور النوع.","",
    "## بعد كل صورة مقبولة",
    "1. احفظها باسم **`id.png` بالضبط** (عمود «اسم الحفظ»). جيمناي لا يسمّي ملفاتك.",
    "2. اجمع صور الفصل في فولدر واحد وأرسله لي (zip) بعد أول 8 إلى 10 صور، ولا تنتظر الاكتمال. أنا أحوّل وأقصّ وأزيل الخلفيات وأدفع. **لا تحوّل ولا تصغّر بنفسك.**","",
    "## الطبقة A: لازمة للتسليم",""]+table(A)+["","## الطبقة B: تحسينية",""]+table(B)+["","## ما يخص هذا الفصل",tips[n],"",
    "## متى ترفض الصورة وتعيد؟","نص أو حروف داخل الصورة، يد أو وجه مشوّه، أشخاص في خلفية بلا شخصيات، ألوان نيون، أسلوب يختلف عن المرجع، أيقونة خلفها مشهد بدل رمادي مسطح، أو أكثر من شيء في الأيقونة. نقاط القبول تحت كل برومبت. **إن فشلت صورة مرتين:** اتركها واكتب لي رقمها.","",
    "## الأحجام النهائية (شغلي أنا)","خلفية ≤250KB، شخصية ≤200KB، أيقونة ≤40KB."]
    open(f"ch{n}/00_README_MAZIN.md","w",encoding='utf-8').write("\n".join(L)+"\n")
    print(n,len(rows),'A',len(A),'bg/char/icon',[len(g[k]) for k in('bg','char','icon')])
